// Deterministic reference formatting (APA 7 + BibTeX) for each summarized paper
const parseAuthors = a => {
  if (Array.isArray(a)) return a;
  try { const v = JSON.parse(a || '[]'); return Array.isArray(v) ? v : []; } catch { return a ? [String(a)] : []; }
};
const apaName = full => {
  const parts = String(full).trim().split(/\s+/);
  if (parts.length < 2) return parts[0] || '';
  const last = parts.pop();
  return `${last}, ${parts.map(p => p[0].toUpperCase() + '.').join(' ')}`;
};

return $input.all().map(({ json: p }) => {
  const authors = parseAuthors(p.authors);
  const year = p.publication_date ? new Date(p.publication_date).getFullYear() : 'n.d.';
  const title = (p.title || 'Untitled').replace(/\s+/g, ' ').trim();

  let authorStr = authors.slice(0, 20).map(apaName);
  authorStr = authorStr.length > 1
    ? authorStr.slice(0, -1).join(', ') + ', & ' + authorStr.slice(-1)
    : (authorStr[0] || 'Unknown author');

  const venue = p.arxiv_id ? `arXiv preprint arXiv:${p.arxiv_id}` : (p.source === 'semantic_scholar' ? 'Semantic Scholar' : '');
  const link = p.doi ? `https://doi.org/${p.doi}` : (p.url || '');
  const citation_apa = `${authorStr} (${year}). ${title}. ${venue ? venue + '. ' : ''}${link}`.trim();

  const firstLast = (String(authors[0] || 'unknown').trim().split(/\s+/).pop() || 'unknown')
    .toLowerCase().replace(/[^a-z]/g, '');
  const firstWord = (title.toLowerCase().match(/[a-z]{4,}/) || ['paper'])[0];
  const key = `${firstLast}${year}${firstWord}`;
  const esc = s => String(s).replace(/[{}]/g, '');
  const fields = [
    `  title = {${esc(title)}}`,
    `  author = {${esc(authors.join(' and ') || 'Unknown')}}`,
    `  year = {${year}}`,
    p.doi ? `  doi = {${p.doi}}` : null,
    p.arxiv_id ? `  eprint = {${p.arxiv_id}},\n  archivePrefix = {arXiv}` : null,
    link ? `  url = {${link}}` : null,
    p.extracted_keywords ? `  keywords = {${esc(p.extracted_keywords)}}` : null
  ].filter(Boolean).join(',\n');
  const bibtex = `@${p.arxiv_id ? 'misc' : 'article'}{${key},\n${fields}\n}`;

  return { json: {
    paper_id: p.paper_id, topic_id: p.topic_id, title, pdf_url: p.pdf_url || '',
    citation_apa, bibtex,
    pdf_file_name: `${p.paper_id}_${firstLast}${year}.pdf`
  }};
});

// Attach the Drive outcome to each paper's reference (from "Attach Reference").
// Item i of this branch maps to the paired input item, or to position i when the
// whole Drive call failed (e.g. missing credential) and pairing info is absent.
const refs = $('Attach Reference').all().map(i => i.json);
return $input.all().map((it, i) => {
  const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = (p && typeof p.item === 'number') ? p.item : i;
  const ref = refs[idx] || refs[i] || {};
  return { json: { ...ref, pdf_status: 'stored', drive_file_url: it.json.id ? `https://drive.google.com/file/d/${it.json.id}/view` : '', processing_error: '' } };
});

// Attach the Drive outcome to each paper's reference (from "Attach Reference").
// Item i of this branch maps to the paired input item, or to position i when the
// whole Drive call failed (e.g. missing credential) and pairing info is absent.
const refs = $('Attach Reference').all().map(i => i.json);
return $input.all().map((it, i) => {
  const p = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = (p && typeof p.item === 'number') ? p.item : i;
  const ref = refs[idx] || refs[i] || {};
  return { json: { ...ref, pdf_status: 'drive_upload_failed', drive_file_url: '', processing_error: 'Drive upload failed: ' + String(it.json.error?.message || it.json.error || 'unknown').split(' - ')[0].slice(0, 200) } };
});

// Attach the PDF outcome to the reference built in "Build Citations"
const ref = $('Build Citations').item.json;
return { json: {
  ...ref,
  pdf_status: 'download_failed',
  drive_file_url: '',
  processing_error: 'PDF download failed: ' + String($json.error?.message || $json.error || 'unknown').split(' - ')[0].slice(0, 200)
} };

// Attach the PDF outcome to the reference built in "Build Citations"
const ref = $('Build Citations').item.json;
return { json: {
  ...ref,
  pdf_status: 'no_link',
  drive_file_url: '',
  processing_error: ''
} };

// One BibTeX library file per run, uploaded to Google Drive
const entries = $('Build Citations').all().map(i => i.json.bibtex);
const stamp = $now.toFormat('yyyy-LL-dd_HHmm');
return [{ json: {
  file_name: `research_library_${stamp}.bib`,
  bib: `% AI Research Assistant – references added ${stamp}\n\n` + entries.join('\n\n') + '\n',
  references: entries.length
}}];

const rows = $('Collect PDF Outcomes').all().map(i => i.json);
const tally = rows.reduce((t, r) => (t[r.pdf_status] = (t[r.pdf_status] || 0) + 1, t), {});
return [{ json: {
  workflow: $workflow.name,
  event: 'references_archived',
  level: (tally.download_failed || tally.drive_upload_failed) ? 'warning' : 'info',
  message: `${rows.length} reference(s) archived`,
  details: { pdf_status: tally },
  execution_id: $execution.id
}}];

// Searchable repository + related-paper recommendation (deterministic keyword scoring)
// GET /webhook/research/papers/search?q=...&topic_id=...&limit=10
// GET /webhook/research/papers/search?paper_id=PAPER-...   -> related papers
const query = $('Search Request').first().json.query || {};
const rows = $input.all().map(i => i.json).filter(r => r.paper_id);
const limit = Math.min(Math.max(parseInt(query.limit || '10', 10) || 10, 1), 50);

let q = String(query.q || '').toLowerCase();
let exclude = null;
if (query.paper_id) {
  const base = rows.find(r => r.paper_id === query.paper_id);
  if (!base) return [{ json: { status_code: 404, success: false, message: `paper_id ${query.paper_id} not found` } }];
  q = `${base.extracted_keywords || ''} ${base.research_category || ''}`.toLowerCase();
  exclude = base.paper_id;
}
const terms = [...new Set(q.split(/[^a-z0-9]+/).filter(t => t.length > 2))];
if (!terms.length) {
  return [{ json: { status_code: 400, success: false, message: 'Provide ?q=<search terms> or ?paper_id=<id>' } }];
}

const count = (text, t) => (String(text || '').toLowerCase().match(new RegExp(`\\b${t}`, 'g')) || []).length;
const results = rows
  .filter(r => r.paper_id !== exclude)
  .filter(r => !query.topic_id || r.topic_id === query.topic_id)
  .map(r => {
    const score = terms.reduce((s, t) =>
      s + 3 * count(r.title, t) + 2 * count(r.extracted_keywords, t) + count(r.summary, t) + count(r.abstract, t), 0);
    return { score, r };
  })
  .filter(x => x.score > 0)
  .sort((a, b) => b.score - a.score || (b.r.relevance_score || 0) - (a.r.relevance_score || 0))
  .slice(0, limit)
  .map(({ score, r }) => ({
    paper_id: r.paper_id, title: r.title, authors: r.authors, publication_date: r.publication_date,
    topic_id: r.topic_id, category: r.research_category, keywords: r.extracted_keywords,
    summary: r.summary, url: r.url, pdf_status: r.pdf_status, drive_file_url: r.drive_file_url,
    citation_apa: r.citation_apa, relevance_score: r.relevance_score, match_score: score
  }));

return [{ json: {
  status_code: 200, success: true,
  mode: exclude ? 'related' : 'search', query: exclude ? { paper_id: exclude } : { q: query.q, topic_id: query.topic_id || null },
  count: results.length, results
}}];

// Carry the paper's reference fields together with the downloaded PDF,
// so later steps never depend on paired-item lookups through Google Drive.
return { json: { ...$('Build Citations').item.json }, binary: $input.item.binary };
